"use strict";

// The NEGATIVE control that makes RWF-024 sound rather than merely
// conservative. It carries the identical always-throwing call in the two
// positions that are genuinely NOT object-construction time, and its
// later export must therefore REMAIN authoritative:
//
//  1. `lazy() { return bail(); }` -- a method BODY, run only when called;
//  2. a computed key on an object literal built INSIDE a function that
//     nothing calls at module scope -- deferred until `configure()` runs,
//     which it never does here.
//
// Unlike RWF-018/019's class fixtures, there is deliberately NO "ordinary
// VALUE" control here: an object literal's ordinary property VALUE is NOT
// deferred (see the ground-truth fixture's `forms.js`), so a value-position
// control would not demonstrate safety -- it would demonstrate the
// documented, adjacent gap this task does not close. Both positions here
// are proven safe in-process in the ground-truth fixture's `c.js`.
function dangerousOp(input) {
  return "danger:" + input;
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("throws only on invocation, or when configure() runs");
}

function configure() {
  return {
    [bail()]: 1,
  };
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  const installed = {
    lazy() {
      return bail();
    },
  };
  void installed;
}

safeOp.configure = configure;
module.exports = safeOp;
